-- SQLite. First-observed cohort; right-censored cells omitted.
WITH active AS (SELECT DISTINCT customer_id,CAST(substr(order_date,1,4) AS INTEGER)*12+CAST(substr(order_date,6,2) AS INTEGER)-1 AS month FROM orders), first_seen AS (SELECT customer_id,MIN(month) cohort FROM active GROUP BY customer_id), sizes AS (SELECT cohort,COUNT(*) cohort_size FROM first_seen GROUP BY cohort), cutoff AS (SELECT MAX(month) last_month FROM active), offsets AS (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 6 UNION ALL SELECT 12), counts AS (SELECT f.cohort,a.month-f.cohort month_offset,COUNT(*) active_customers FROM active a JOIN first_seen f USING(customer_id) GROUP BY f.cohort,month_offset) SELECT s.cohort,o.n month_offset,s.cohort_size,COALESCE(c.active_customers,0) active_customers,ROUND(100.0*COALESCE(c.active_customers,0)/s.cohort_size,2) retention_pct FROM sizes s CROSS JOIN offsets o CROSS JOIN cutoff t LEFT JOIN counts c ON c.cohort=s.cohort AND c.month_offset=o.n WHERE s.cohort+o.n<=t.last_month ORDER BY s.cohort,o.n;